//! Exact operation identity of every retained old template against frozen width01.
use crate::point_add::trailmix_port::circuit::Circuit;
fn build(block:usize,j:usize,reference:bool)->Vec<crate::circuit::Op>{let mut c=Circuit::new();c.b.count_only=false;c.b.fiat_hash=None;let m=c.alloc_qreg_bits("fold20",20);let p1=c.alloc_qreg("p1");let p2=c.alloc_qreg("p2");let it=c.alloc_qreg("it");let w1=c.alloc_qreg_bits("w1",259);let w2=c.alloc_qreg_bits("w2",259);let h=c.alloc_qreg_bits("helpers",23);if reference{super::q792_step_width01_reference_r01::step(&mut c,&m,&p1,&p2,&it,&w1,&w2,&h,j,block);}else{super::q792_step_r01::step(&mut c,&m,&p1,&p2,&it,&w1,&w2,&h,j,block);}assert_eq!(c.b.next_qubit,564);c.into_builder().ops}
pub fn run(){std::env::set_var("Q796_PARITY","1");std::env::set_var("Q795_PHASE_LOAN","1");assert!(std::env::var_os("FOLD20_STEP_FULLWIDTH").is_none());assert!(std::env::var_os("Q795_TRACE").is_none());let mut count=0;for b in 0..202{for j in 0..4{if super::q792_t_only_selection_r01::CHOOSE_NEW[b][j]{continue;}let actual=build(b,j,false);let reference=build(b,j,true);assert_eq!(actual,reference,"retained template differs block={b} j={j}");let t=actual.iter().filter(|o|o.kind==crate::circuit::OperationType::CCX).count();assert_eq!((actual.len(),t),super::q792_t_only_selection_r01::EXPECTED[b][j]);count+=1;eprintln!("T_ONLY_RETAINED_BYTE_IDENTITY block={b} j={j} N={} T={t} PASS",actual.len());}}eprintln!("T_ONLY_SELECTED_OLD_PASS old_templates={count} all_ops_identical=true protected_unchanged=true");}
